function renderPractice(){const qs=state.questions;return `${head('PRACTISE & IMPROVE','Practice quiz','Answer original practice questions, check explanations, and save mistakes to your error book.',`<div class="field" style="margin:0;min-width:150px"><select id="quiz-subject">${state.subjects.map(s=>`<option ${s===state.quizSubject?'selected':''}>${esc(s)}</option>`).join('')}</select></div>`)}<div class="notice">These are original practice questions for learning. They are <b>not official KNEC examination papers</b>.</div>${qs.length?qs.map((q,i)=>`<article class="question-card"><div class="question-meta">QUESTION ${i+1} · ${esc(q.subject)} · ${esc(q.topic||'Practice')}</div><h3>${esc(q.question)}</h3><div class="options">${q.options.map((o,j)=>`<label class="option"><input type="radio" name="${q.id}" value="${esc(o)}" ${state.answers[q.id]===o?'checked':''} ${state.feedback[q.id]?'disabled':''}> <span>${String.fromCharCode(65+j)}. ${esc(o)}</span></label>`).join('')}</div>${state.feedback[q.id]?`<div class="feedback ${state.feedback[q.id].correct?'good':'bad'}"><b>${state.feedback[q.id].correct?'Correct — well done!':'Not quite. Review the method.'}</b><br>Answer: ${esc(state.feedback[q.id].correctAnswer)}<br>${esc(state.feedback[q.id].explanation)}</div>`:`<div class="button-row" style="margin-top:13px"><button class="primary" data-action="check-answer" data-id="${q.id}">Check answer</button></div>`}</article>`).join(''):`<div class="panel empty-state"><div class="empty-icon">▤</div><b>No practice questions for this subject yet</b><p>Choose another subject, or use the AI tutor to explore this topic.</p><button class="secondary" data-action="tutor">Open AI tutor</button></div>`}<div class="button-row">${btn('Load another subject','reload-quiz','secondary')}${btn('Back to overview','home','ghost')}</div>`}
